import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def check_condition(n, divisors):
    tau_n = len(divisors)

    # Condition: n must have at least 5 positive divisors
    if tau_n < 5:
        return None, "Tau < 5"

    # a: 2nd smallest divisor
    # b: 3rd smallest divisor
    # c: 5th smallest divisor
    # Divisors are 1-indexed: d1=1, d2=a, d3=b, d4, d5=c, ...
    a = divisors[1]
    b = divisors[2]
    c = divisors[4]

    # Check the equation: (a + b + c)^2 = a^2 + b^2 + c^2 + 2n
    # Which is equivalent to: n = ab + ac + bc
    LHS = a * b + a * c + b * c

    if LHS == n:
        return (a, b, c), f"Found: n={n}, tau(n)={tau_n}, a={a}, b={b}, c={c}"
    else:
        return (a, b, c), f"Checked: n={n}, tau(n)={tau_n}, a={a}, b={b}, c={c}. Condition failed (LHS={LHS} != n)."

# Search range for n. Let's check up to n=100 first.
N_MAX = 100
results = []

for n in range(1, N_MAX + 1):
    divisors = get_divisors(n)
    result = check_condition(n, divisors)

    if result is not None:
        if isinstance(result[1], str) and "Found" in result[1]:
