    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def check_condition(n):
    divisors = get_divisors(n)

    # Must have at least 5 divisors
    if len(divisors) < 5:
        return None, None

    # a = 2nd smallest divisor (index 1)
    # b = 3rd smallest divisor (index 2)
    # c = 5th smallest divisor (index 4)
    a = divisors[1]
    b = divisors[2]
    c = divisors[4]

    # Check the condition: n = ab + ac + bc
    result = a * b + a * c + b * c

    if result == n:
        tau_n = len(divisors)
        return a, b, c, tau_n
    else:
        return None, None, None, None

# Search up to N=500, starting from 101 (since 100 was done in previous steps)
start_n = 101
end_n = 501
solutions = []

for n in range(start_n, end_n):
    a, b, c, tau_n = check_condition(n)
    if tau_n is not None:
        solutions.append({
            'n': n, 
            'a': a, 
            'b': b, 
            'c': c, 
            'tau(n)': tau_n
        })

print("Found solutions (N > 100, N <= 500):")
for sol in solutions:
